       margin-top: 1rem;
       background: var(--bg-surface-2);
       color: var(--text);
       border-color: var(--border);
     }

     .newsletter-card {
       display: grid;
       grid-template-columns: 1fr auto;
       gap: 1rem;
       align-items: center;
       padding: 1.3rem;
       margin-bottom: 1.5rem;
     }

     .newsletter-card p {
       color: var(--text-muted);
       margin-top: 0.45rem;
     }

     .newsletter-form {
       display: flex;
       gap: 0.75rem;
       min-width: 0;
     }

     .newsletter-form label {
       position: absolute;
       width: 1px;
       height: 1px;
       padding: 0;
       margin: -1px;
       overflow: hidden;
       clip: rect(0, 0, 0, 0);
       white-space: nowrap;
       border: 0;
     }

     .newsletter-form input {
       width: min(340px, 100%);
       min-width: 0;
       padding: 0.95rem 1rem;
       border-radius: 999px;
       background: var(--bg-surface-2);
       color: var(--text);
       border: 1px solid var(--border);
     }

     .newsletter-form input::placeholder {
       color: var(--text-soft);
     }

     .newsletter-form button {
       padding: 0.95rem 1.25rem;
       border-radius: 999px;
       border: 1px solid var(--accent);
       background: var(--accent);
       color: var(--accent-contrast);
       font-weight: 800;
       cursor: pointer;
     }

     .status {
       min-height: 1.5rem;
       margin-top: 0.8rem;
       color: var(--success);
       font-weight: 600;
     }

     .footer {
       padding: 1rem 0 2.4rem;
       color: var(--text-soft);
       font-size: 0.94rem;
     }

     .footer-inner {
       display: flex;
       flex-wrap: wrap;
       justify-content: space-between;
       gap: 1rem;
       border-top: 1px solid var(--border);
       padding-top: 1rem;
     }

     .footer nav {
       display: flex;
       gap: 1rem;
       flex-wrap: wrap;
     }

     .is-hidden {
       display: none !important;
     }

     @media (max-width: 1024px) {
       .hero-grid,
       .stories-grid,
       .newsletter-card,
       .story-card.featured-story {
         grid-template-columns: 1fr;
       }

       .product-grid {
         grid-template-columns: repeat(2, minmax(0, 1fr));
       }

       .deal-layout {
         grid-template-columns: 1fr;
       }

       .metric-row {
         grid-template-columns: repeat(3, minmax(0, 1fr));
       }
     }

     @media (max-width: 720px) {
       .topbar-inner {
         align-items: start;
         flex-direction: column;
       }

       .nav {
         flex-wrap: wrap;
         gap: 0.85rem 1rem;
       }

       h1 {
         max-width: 11ch;
       }

       .product-grid,
       .metric-row,
       .countdown {
         grid-template-columns: 1fr 1fr;
       }

       .newsletter-form {
         flex-direction: column;
       }

       .newsletter-form input,
       .newsletter-form button {
         width: 100%;
       }
     }

     @media (max-width: 560px) {
       .hero {
         padding-top: 2rem;
       }

       .product-grid,
       .metric-row,
       .countdown {
         grid-template-columns: 1fr;
       }

       .spotlight-meta,
       .deal-banner {
         align-items: start;
         flex-direction: column;
       }
     }

