       .story-card,
       .newsletter-card,
       .metric,
       .spotlight,
       .product-art,
       .story-visual,
       .cart-button,
       .cta-secondary,
       .product-button,
       .chip,
       .deal-button,
       .story-link,
       .newsletter-form input {
         border-color: ButtonBorder;
         background: Canvas;
         color: CanvasText;
         box-shadow: none;
