      border-color: var(--border-strong);
    }

    .hero-side {
      display: grid;
      gap: 1rem;
      padding: 1.25rem;
      min-width: 0;
    }

    .spotlight {
      display: grid;
      grid-template-columns: minmax(0, 1fr);
      align-content: space-between;
      min-height: 100%;
      padding: 1.2rem;
      border-radius: var(--radius-lg);
      background:
        linear-gradient(145deg, #1f2740 0%, #101421 62%, #0f1524 100%);
      border: 1px solid var(--border);
    }

    .spotlight-art {
      width: 100%;
      aspect-ratio: 1 / 0.95;
      border-radius: 22px;
      background:
        radial-gradient(circle at 30% 25%, #91dbff 0, #91dbff 18%, transparent 19%),
        radial-gradient(circle at 68% 38%, #ffd67c 0, #ffd67c 12%, transparent 13%),
        linear-gradient(135deg, #262d47 0%, #141a2b 55%, #0e1220 100%);
      border: 1px solid var(--border);
      margin-bottom: 1rem;
    }

    .spotlight-meta {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
    }

    .spotlight-meta p {
      color: var(--text-muted);
      max-width: 20ch;
    }

    .metric-row {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.85rem;
    }

    .metric {
      padding: 1rem;
      border-radius: var(--radius-md);
      border: 1px solid var(--border);
      background: var(--bg-surface-2);
      min-width: 0;
    }

    .metric strong {
      display: block;
      font-size: 1.25rem;
      margin-bottom: 0.2rem;
    }

    .metric span {
      color: var(--text-soft);
      font-size: 0.92rem;
    }

    .section {
      padding: 1.5rem 0;
    }

    .section-card {
      padding: clamp(1.25rem, 3vw, 2rem);
    }

    .section-head {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.1rem;
    }

    .section-head p {
      color: var(--text-muted);
      max-width: 56ch;
    }

    .chip-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin-bottom: 1.1rem;
    }

    .chip {
      padding: 0.7rem 1rem;
      background: transparent;
      color: var(--text-muted);
      border-color: var(--border);
      font-weight: 700;
    }

    .chip[aria-pressed="true"] {
      background: var(--text);
      color: var(--accent-contrast);
      border-color: var(--text);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      padding: 1rem;
      min-width: 0;
    }

    .product-art {
      aspect-ratio: 4 / 3.15;
      border-radius: 18px;
      border: 1px solid var(--border);
      margin-bottom: 0.9rem;
      background: linear-gradient(135deg, #1d2539 0%, #111522 100%);
      position: relative;
      overflow: hidden;
    }

    .product-art::before,
    .product-art::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
    }

    .product-art::before {
      width: 62%;
      height: 68%;
      left: 18%;
      top: 14%;
      background: linear-gradient(180deg, #32405f 0%, #171e31 100%);
      border: 1px solid #415073;
    }

    .product-art::after {
      width: 24%;
      height: 24%;
      right: 12%;
      top: 12%;
      background: #8bd3ff;
      box-shadow: 0 0 0 12px #102133;
    }

    .product-card h3,
    .deal-card h3,
    .story-card h3 {
      font-size: 1.05rem;
      line-height: 1.2;
    }

    .product-meta {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 0.8rem;
      margin-top: 0.8rem;
      color: var(--text-muted);
      font-size: 0.94rem;
    }

    .product-meta strong {
      color: var(--text);
      font-size: 1.05rem;
    }

    .product-button {
      width: 100%;
      margin-top: 0.9rem;
      padding: 0.85rem 1rem;
      background: var(--bg-surface-2);
      color: var(--text);
      border-color: var(--border);
      font-weight: 700;
    }

    .product-button[aria-pressed="true"] {
      background: var(--success);
      color: #06130c;
      border-color: var(--success);
    }

    .deal-layout {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .deal-card {
      padding: 1.2rem;
      min-width: 0;
    }

    .deal-card.featured {
      grid-column: span 1;
      background:
        radial-gradient(circle at top right, #2c3655 0, #1a2032 28%, #121726 55%, #10131e 100%);
    }

    .deal-card .deal-badge,
    .story-tag {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: #1c2233;
      color: var(--warning);
      border: 1px solid #3b4560;
      font-size: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .deal-card p,
    .story-card p {
      color: var(--text-muted);
      margin-top: 0.8rem;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.6rem;
      margin: 1rem 0 1.2rem;
    }

    .countdown div {
      padding: 0.8rem 0.7rem;
      text-align: center;
      background: var(--bg-surface-2);
      border: 1px solid var(--border);
      border-radius: 16px;
    }

    .countdown strong {
      display: block;
      font-size: 1.25rem;
      line-height: 1;
    }

    .countdown span {
      color: var(--text-soft);
      font-size: 0.8rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .deal-grid {
      display: grid;
      gap: 1rem;
    }

    .deal-stack {
      display: grid;
      gap: 1rem;
    }

    .deal-banner {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      padding: 1rem 1.1rem;
      border-radius: var(--radius-md);
      background: var(--bg-surface-2);
      border: 1px solid var(--border);
    }

    .deal-banner strong {
      display: block;
      font-size: 1rem;
    }

    .deal-banner span {
      color: var(--text-soft);
      font-size: 0.92rem;
    }

    .deal-button {
      background: transparent;
      color: var(--text);
      border-color: var(--border-strong);
    }

    .stories-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
    }

    .story-card {
      padding: 1.2rem;
      min-width: 0;
    }

    .story-card.featured-story {
      display: grid;
      grid-template-columns: minmax(0, 0.95fr) minmax(260px, 1.05fr);
      gap: 1rem;
      align-items: center;
    }

    .story-visual {
      min-height: 300px;
      border-radius: 22px;
      border: 1px solid var(--border);
      background:
        linear-gradient(135deg, #1f2741 0%, #111723 100%);
      position: relative;
      overflow: hidden;
    }

    .story-visual::before {
      content: "";
      position: absolute;
      inset: 12% 12% 20% 12%;
      border-radius: 20px;
      border: 1px solid #425170;
      background:
        linear-gradient(180deg, #2b3651 0%, #151b29 100%);
    }

    .story-visual::after {
      content: "";
      position: absolute;
      inset: auto 20% 14% 20%;
      height: 9%;
      border-radius: 999px;
      background: #8bd3ff;
      box-shadow: 0 -38px 0 0 #ffc36b, 0 -76px 0 0 #7ee0b2;
    }

    .story-list {
      display: grid;
      gap: 1rem;
    }

    .story-card small {
      display: inline-block;
      margin-top: 0.8rem;
      color: var(--text-soft);
      font-size: 0.86rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .story-link {
      margin-top: 1rem;
      background: var(--bg-surface-2);
      color: var(--text);
      border-color: var(--border);
    }

    .newsletter-card {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      padding: 1.3rem;
      margin-bottom: 1.5rem;
    }

    .newsletter-card p {
      color: var(--text-muted);
      margin-top: 0.45rem;
    }

    .newsletter-form {
      display: flex;
      gap: 0.75rem;
      min-width: 0;
    }

    .newsletter-form label {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .newsletter-form input {
      width: min(340px, 100%);
      min-width: 0;
      padding: 0.95rem 1rem;
      border-radius: 999px;
      background: var(--bg-surface-2);
      color: var(--text);
      border: 1px solid var(--border);
    }

    .newsletter-form input::placeholder {
      color: var(--text-soft);
    }

    .newsletter-form button {
      padding: 0.95rem 1.25rem;
      border-radius: 999px;
      border: 1px solid var(--accent);
      background: var(--accent);
      color: var(--accent-contrast);
      font-weight: 800;
      cursor: pointer;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 0.8rem;
      color: var(--success);
      font-weight: 600;
    }

    .footer {
      padding: 1rem 0 2.4rem;
      color: var(--text-soft);
      font-size: 0.94rem;
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      border-top: 1px solid var(--border);
      padding-top: 1rem;
    }

    .footer nav {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .is-hidden {
      display: none !important;
    }

    @media (max-width: 1024px) {
      .hero-grid,
      .stories-grid,
      .newsletter-card,
      .story-card.featured-story {
        grid-template-columns: 1fr;
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .deal-layout {
        grid-template-columns: 1fr;
      }

      .metric-row {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }
    }

    @media (max-width: 720px) {
      .topbar-inner {
        align-items: start;
        flex-direction: column;
      }

      .nav {
        flex-wrap: wrap;
        gap: 0.85rem 1rem;
      }

      h1 {
        max-width: 11ch;
      }

      .product-grid,
      .metric-row,
      .countdown {
        grid-template-columns: 1fr 1fr;
      }

      .newsletter-form {
        flex-direction: column;
      }

      .newsletter-form input,
      .newsletter-form button {
        width: 100%;
      }
    }

    @media (max-width: 560px) {
      .hero {
        padding-top: 2rem;
      }

      .product-grid,
      .metric-row,
      .countdown {
        grid-template-columns: 1fr;
      }

      .spotlight-meta,
      .deal-banner {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (forced-colors: active) {
      * {
        forced-color-adjust: auto;
      }

      body,
      .topbar {
        background: Canvas;
        color: CanvasText;
      }

      .hero-copy,
      .hero-side,
      .section-card,
      .product-card,
      .deal-card,
      .story-card,
      .newsletter-card,
      .metric,
      .spotlight,
      .product-art,
      .story-visual,
      .cart-button,
      .cta-secondary,
      .product-button,
      .chip,
      .deal-button,
      .story-link,
      .newsletter-form input {
        border-color: ButtonBorder;
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
      }

      .cta-primary,
      .cart-pill,
      .chip[aria-pressed="true"],
      .product-button[aria-pressed="true"],
      .newsletter-form button {
        background: Highlight;
        color: HighlightText;
        border-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <header class="topbar">
    <div class="shell topbar-inner">
      <a class="brand" href="#" aria-label="Northstar Retail home">
        <span class="brand-mark" aria-hidden="true"></span>
        Northstar Retail
      </a>

      <nav class="nav" aria-label="Primary">
        <a href="#featured">Featured</a>
        <a href="#deals">Deals</a>
        <a href="#stories">Stories</a>
      </nav>

      <button class="cart-button" type="button" aria-label="Shopping bag, 2 items">
        Bag
        <span class="cart-pill" aria-hidden="true">2</span>
      </button>
    </div>
  </header>

  <main id="main">
    <section class="hero">
      <div class="shell hero-grid">
        <div class="hero-copy">
          <span class="eyebrow">New season / dark edit</span>
          <h1>Retail essentials, styled for the after-hours.</h1>
          <p>Discover premium layers, low-key statement pieces, and editorial picks curated for a clean, modern wardrobe.</p>
          <div class="hero-actions">
            <a class="cta-primary" href="#featured">Shop featured</a>
            <a class="cta-secondary" href="#stories">Read the journal</a>
          </div>
        </div>

        <aside class="hero-side" aria-label="Brand highlights">
          <div class="spotlight">
            <div class="spotlight-art" aria-hidden="true"></div>
            <div class="spotlight-meta">
              <div>
                <span class="eyebrow" style="margin-bottom: 0.5rem;">Spotlight</span>
                <h2 style="font-size: 1.4rem; letter-spacing: -0.03em;">Arc jacket collection</h2>
                <p>Weather-ready tailoring with soft structure and a matte finish.</p>
              </div>
              <strong style="font-size: 1.1rem;">From $180</strong>
            </div>
          </div>

          <div class="metric-row" aria-label="Store metrics">
            <div class="metric">
              <strong>24h</strong>
              <span>fast dispatch</span>
            </div>
            <div class="metric">
              <strong>4.8/5</strong>
              <span>customer rating</span>
            </div>
            <div class="metric">
              <strong>80+</strong>
              <span>new arrivals</span>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <section id="featured" class="section">
      <div class="shell section-card">
        <div class="section-head">
          <div>
            <span class="eyebrow">Featured products</span>
            <h2 style="font-size: clamp(1.7rem, 3vw, 2.4rem); letter-spacing: -0.04em;">Best-in-class pieces for every layer</h2>
          </div>
          <p>Use the filters to browse standout picks across outerwear, sneakers, accessories, and everyday essentials.</p>
        </div>

        <div class="chip-row" role="toolbar" aria-label="Featured product filters">
          <button class="chip" type="button" aria-pressed="true" data-filter="all">All</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="outerwear">Outerwear</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="footwear">Footwear</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="accessories">Accessories</button>
          <button class="chip" type="button" aria-pressed="false" data-filter="daily">Daily wear</button>
        </div>

        <div class="product-grid" id="productGrid">
          <article class="product-card" data-category="outerwear">
            <div class="product-art" aria-hidden="true"></div>
            <h3>Atlas shell jacket</h3>
            <div class="product-meta"><span>Lightweight outerwear</span><strong>$220</strong></div>
            <button class="product-button" type="button" aria-pressed="false" data-product-name="Atlas shell jacket" aria-label="Add to bag: Atlas shell jacket">Add to bag</button>
          </article>
          <article class="product-card" data-category="footwear">
            <div class="product-art" aria-hidden="true"></div>
            <h3>Vector runner</h3>
            <div class="product-meta"><span>Responsive cushioning</span><strong>$145</strong></div>
            <button class="product-button" type="button" aria-pressed="false" data-product-name="Vector runner" aria-label="Add to bag: Vector runner">Add to bag</button>
          </article>
          <article class="product-card" data-category="accessories">
            <div class="product-art" aria-hidden="true"></div>
            <h3>Mono carry tote</h3>
            <div class="product-meta"><span>Reinforced canvas</span><strong>$88</strong></div>
            <button class="product-button" type="button" aria-pressed="false" data-product-name="Mono carry tote" aria-label="Add to bag: Mono carry tote">Add to bag</button>
          </article>
          <article class="product-card" data-category="daily">
            <div class="product-art" aria-hidden="true"></div>
            <h3>Softline knit tee</h3>
            <div class="product-meta"><span>Heavyweight cotton</span><strong>$54</strong></div>
            <button class="product-button" type="button" aria-pressed="false" data-product-name="Softline knit tee" aria-label="Add to bag: Softline knit tee">Add to bag</button>
          </article>
        </div>
        <div class="status" id="bagStatus" aria-live="polite" aria-atomic="true"></div>
      </div>
    </section>

    <section id="deals" class="section">
      <div class="shell section-card">
        <div class="section-head">
          <div>
            <span class="eyebrow">Deals</span>
            <h2 style="font-size: clamp(1.7rem, 3vw, 2.4rem); letter-spacing: -0.04em;">Limited-time offers, updated live</h2>
          </div>
          <p>Save on elevated staples and bundle offers before the campaign closes.</p>
        </div>

        <div class="deal-layout">
          <article class="deal-card featured">
            <span class="deal-badge">48-hour event</span>
            <h3 style="margin-top: 0.9rem; font-size: clamp(1.5rem, 2.4vw, 2rem);">Spend $200, get 20% off outerwear</h3>
            <p>Build a sharp cold-weather uniform with discounted jackets, overshirts, and insulated layers.</p>
            <div class="countdown" aria-label="Sale countdown">
              <div><strong id="days">--</strong><span>Days</span></div>
              <div><strong id="hours">--</strong><span>Hours</span></div>
              <div><strong id="minutes">--</strong><span>Minutes</span></div>
              <div><strong id="seconds">--</strong><span>Seconds</span></div>
            </div>
            <a class="deal-button" href="#featured">Shop the offer</a>
          </article>

          <div class="deal-stack">
            <article class="deal-card">
              <span class="deal-badge">New markdown</span>
              <h3 style="margin-top: 0.9rem;">Footwear duo: save 15% on second pair</h3>
              <p>Complete your weekly rotation with low-profile runners and everyday slip-ons.</p>
            </article>
            <article class="deal-card">
              <span class="deal-badge">Member perk</span>
              <h3 style="margin-top: 0.9rem;">Free expedited shipping over $120</h3>
              <p>Fast delivery on essentials, gifts, and last-minute wardrobe upgrades.</p>
            </article>
          </div>

          <article class="deal-card">
            <span class="deal-badge">Bundle and save</span>
            <h3 style="margin-top: 0.9rem;">Three-piece daily set</h3>
            <p>Pair a knit tee, relaxed trouser, and carry tote for a complete off-duty edit.</p>
            <a class="story-link" href="#stories">See editorial pairing</a>
          </article>
        </div>
      </div>
    </section>

    <section id="stories" class="section">
      <div class="shell section-card">
        <div class="section-head">
          <div>
            <span class="eyebrow">Editorial content</span>
            <h2 style="font-size: clamp(1.7rem, 3vw, 2.4rem); letter-spacing: -0.04em;">Stories that frame the collection</h2>
          </div>
          <p>Thoughtful styling notes, buying guides, and seasonal edits from the Northstar team.</p>
        </div>

        <div class="stories-grid">
          <article class="story-card featured-story">
            <div class="story-visual" aria-hidden="true"></div>
            <div>
              <span class="story-tag">Editor’s note</span>
              <h3 style="margin-top: 0.9rem; font-size: clamp(1.3rem, 2vw, 1.7rem);">How to build a monochrome wardrobe without losing depth</h3>
              <p>Contrast texture, structure, and shine to keep a tonal look dimensional from day to night.</p>
              <small>5 minute read</small>
              <br />
              <a class="story-link" href="#">Read the feature</a>
            </div>
          </article>

          <div class="story-list">
            <article class="story-card">
              <span class="story-tag">Style guide</span>
              <h3 style="margin-top: 0.9rem;">Three ways to wear the Atlas shell jacket</h3>
              <p>Take it from commute mode to dinner-ready with a single layer swap.</p>
              <small>Outfit ideas</small>
            </article>
            <article class="story-card">
              <span class="story-tag">Buying guide</span>
              <h3 style="margin-top: 0.9rem;">Choosing the right runner for everyday mileage</h3>
              <p>Support, feel, and durability explained in a simple comparison.</p>
              <small>Product education</small>
            </article>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="shell newsletter-card">
        <div>
          <span class="eyebrow">Stay in the loop</span>
          <h2 style="font-size: clamp(1.5rem, 2.5vw, 2rem); letter-spacing: -0.04em;">Get weekly drops, early access, and private offers.</h2>
          <p>Join the list for product launches and editorial updates tailored to your inbox.</p>
        </div>
        <form class="newsletter-form" id="newsletterForm">
          <label for="email">Email address</label>
          <input id="email" name="email" type="email" placeholder="name@example.com" autocomplete="email" required />
          <button type="submit">Join list</button>
        </form>
        <div class="status" id="newsletterStatus" aria-live="polite" aria-atomic="true"></div>
      </div>
    </section>
  </main>

  <footer class="footer">
    <div class="shell footer-inner">
      <div>Northstar Retail © 2026</div>
      <nav aria-label="Footer">
        <a href="#featured">Products</a>
        <a href="#deals">Deals</a>
        <a href="#stories">Journal</a>
      </nav>
    </div>
  </footer>

  <script>
    const chips = Array.from(document.querySelectorAll('.chip'));
    const productCards = Array.from(document.querySelectorAll('.product-card'));
    const bagStatus = document.getElementById('bagStatus');
    const newsletterStatus = document.getElementById('newsletterStatus');
    const countdownEls = {
      days: document.getElementById('days'),
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds')
    };
    const newsletterForm = document.getElementById('newsletterForm');
    const saleEndsAt = new Date(Date.now() + 48 * 60 * 60 * 1000);

    function setPressedChip(activeFilter) {
      chips.forEach((chip) => {
        const isActive = chip.dataset.filter === activeFilter;
        chip.setAttribute('aria-pressed', String(isActive));
      });
    }

    function filterProducts(filter) {
      productCards.forEach((card) => {
        const shouldShow = filter === 'all' || card.dataset.category === filter;
        card.classList.toggle('is-hidden', !shouldShow);
      });
    }

    chips.forEach((chip) => {
      chip.addEventListener('click', () => {
        const filter = chip.dataset.filter;
        setPressedChip(filter);
        filterProducts(filter);
      });
    });

    document.querySelectorAll('.product-button').forEach((button) => {
      button.addEventListener('click', () => {
        const pressed = button.getAttribute('aria-pressed') === 'true';
        const nextState = !pressed;
        button.setAttribute('aria-pressed', String(nextState));
        const productName = button.dataset.productName;
        bagStatus.textContent = nextState
          ? `${productName} added to your bag.`
          : `${productName} removed from your bag.`;
      });
    });

    function updateCountdown() {
      const now = new Date();
      const total = Math.max(0, saleEndsAt - now);
      const seconds = Math.floor(total / 1000) % 60;
      const minutes = Math.floor(total / 1000 / 60) % 60;
      const hours = Math.floor(total / 1000 / 60 / 60) % 24;
      const days = Math.floor(total / 1000 / 60 / 60 / 24);

      countdownEls.days.textContent = String(days).padStart(2, '0');
      countdownEls.hours.textContent = String(hours).padStart(2, '0');
      countdownEls.minutes.textContent = String(minutes).padStart(2, '0');
      countdownEls.seconds.textContent = String(seconds).padStart(2, '0');
    }

    updateCountdown();
    setInterval(updateCountdown, 1000);

    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const email = document.getElementById('email');
      if (!newsletterForm.checkValidity()) {
        newsletterForm.reportValidity();
        email.focus();
        return;
      }
      newsletterStatus.textContent = 'Thanks for joining the list. Watch your inbox for the first drop.';
      newsletterForm.reset();
    });
  </script>
</body>
</html>
