  <title>Northstar Retail | Dark Edit</title>
  <meta name="description" content="A polished dark ecommerce home page featuring featured products, live deals, and editorial stories." />
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0d12;
      --bg-elevated: #121622;
      --bg-surface: #171c2a;
      --bg-surface-2: #1d2334;
      --border: #2b3247;
      --border-strong: #3a4460;
      --text: #eef1f8;
      --text-muted: #b4bbcb;
      --text-soft: #8991a6;
      --accent: #8bd3ff;
      --accent-strong: #58b9ff;
      --accent-contrast: #04101b;
      --success: #7ee0b2;
      --warning: #ffc36b;
      --shadow: 0 24px 60px #05070c;
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --max-width: 1180px;
    }

    * { box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-width: 320px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, #1b2440 0, #0b0d12 35%),
        linear-gradient(180deg, #0b0d12 0%, #080a0f 100%);
      color: var(--text);
      line-height: 1.5;
      text-rendering: optimizeLegibility;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      display: block;
      max-width: 100%;
    }

    button,
    input {
      font: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1000;
      transform: translateY(-180%);
      padding: 0.85rem 1.1rem;
      border-radius: 999px;
      background: var(--text);
      color: var(--accent-contrast);
      font-weight: 700;
      box-shadow: var(--shadow);
    }

    .skip-link:focus-visible {
      transform: translateY(0);
    }

    .shell {
      width: min(100% - 2rem, var(--max-width));
      margin: 0 auto;
    }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 100;
      backdrop-filter: blur(18px);
      background: #0b0d12;
      border-bottom: 1px solid var(--border);
    }

    .topbar-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      font-size: 1rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .brand-mark {
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 14px;
      background: linear-gradient(135deg, var(--accent) 0%, #7c8dff 100%);
      box-shadow: inset 0 1px 0 #dff4ff, 0 10px 30px #13254c;
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 1.25rem;
    }

    .nav a {
      color: var(--text-muted);
      font-weight: 600;
    }

    .nav a:hover {
      color: var(--text);
    }

    .cart-button,
    .chip,
    .cta-primary,
    .cta-secondary,
    .product-button,
    .deal-button,
    .story-link {
      border: 1px solid transparent;
      border-radius: 999px;
      cursor: pointer;
      transition: transform 180ms ease, border-color 180ms ease, background-color 180ms ease, color 180ms ease;
    }

    .cart-button:focus-visible,
    .chip:focus-visible,
    .cta-primary:focus-visible,
    .cta-secondary:focus-visible,
    .product-button:focus-visible,
    .deal-button:focus-visible,
    .story-link:focus-visible,
    .newsletter-form input:focus-visible,
    .newsletter-form button:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .cart-button {
      display: inline-flex;
      align-items: center;
      gap: 0.7rem;
      padding: 0.8rem 1rem;
      background: var(--bg-surface);
      color: var(--text);
      border-color: var(--border);
      font-weight: 700;
    }

    .cart-pill {
      min-width: 1.8rem;
      padding: 0.15rem 0.55rem;
      border-radius: 999px;
      background: var(--accent);
      color: var(--accent-contrast);
      text-align: center;
      font-size: 0.85rem;
      font-weight: 800;
    }

    main {
      display: block;
    }

    .hero {
      padding: 3.25rem 0 1.5rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.2fr) minmax(320px, 0.8fr);
      gap: 1.25rem;
      align-items: stretch;
