      color: var(--text-muted);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.9rem;
      margin-top: 1.6rem;
    }

    .cta-primary,
    .cta-secondary,
    .deal-button,
    .story-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.65rem;
      min-height: 3.1rem;
      padding: 0.8rem 1.2rem;
      font-weight: 700;
    }

    .cta-primary {
      background: var(--accent);
      color: var(--accent-contrast);
    }

    .cta-primary:hover,
    .product-button:hover,
    .deal-button:hover,
    .story-link:hover,
    .chip:hover,
    .cart-button:hover,
    .cta-secondary:hover {
      transform: translateY(-1px);
    }

    .cta-secondary {
      background: transparent;
      color: var(--text);
      border-color: var(--border-strong);
    }

    .hero-side {
      display: grid;
      gap: 1rem;
      padding: 1.25rem;
      min-width: 0;
    }

    .spotlight {
      display: grid;
      grid-template-columns: minmax(0, 1fr);
      align-content: space-between;
      min-height: 100%;
      padding: 1.2rem;
      border-radius: var(--radius-lg);
      background:
        linear-gradient(145deg, #1f2740 0%, #101421 62%, #0f1524 100%);
      border: 1px solid var(--border);
    }

    .spotlight-art {
      width: 100%;
      aspect-ratio: 1 / 0.95;
      border-radius: 22px;
      background:
        radial-gradient(circle at 30% 25%, #91dbff 0, #91dbff 18%, transparent 19%),
        radial-gradient(circle at 68% 38%, #ffd67c 0, #ffd67c 12%, transparent 13%),
