    }

    .spotlight-meta {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 1rem;
    }

    .spotlight-meta p {
      color: var(--text-muted);
      max-width: 20ch;
    }

    .metric-row {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.85rem;
    }

    .metric {
      padding: 1rem;
      border-radius: var(--radius-md);
      border: 1px solid var(--border);
      background: var(--bg-surface-2);
      min-width: 0;
    }

    .metric strong {
      display: block;
      font-size: 1.25rem;
      margin-bottom: 0.2rem;
    }

    .metric span {
      color: var(--text-soft);
      font-size: 0.92rem;
    }

    .section {
      padding: 1.5rem 0;
    }

    .section-card {
      padding: clamp(1.25rem, 3vw, 2rem);
    }

    .section-head {
      display: flex;
      flex-wrap: wrap;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.1rem;
    }

    .section-head p {
      color: var(--text-muted);
      max-width: 56ch;
    }

    .chip-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin-bottom: 1.1rem;
    }

    .chip {
      padding: 0.7rem 1rem;
      background: transparent;
      color: var(--text-muted);
      border-color: var(--border);
      font-weight: 700;
    }

    .chip[aria-pressed="true"] {
      background: var(--text);
      color: var(--accent-contrast);
      border-color: var(--text);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      padding: 1rem;
      min-width: 0;
    }

    .product-art {
      aspect-ratio: 4 / 3.15;
      border-radius: 18px;
      border: 1px solid var(--border);
      margin-bottom: 0.9rem;
      background: linear-gradient(135deg, #1d2539 0%, #111522 100%);
      position: relative;
      overflow: hidden;
    }

    .product-art::before,
    .product-art::after {
      content: "";
      position: absolute;
      inset: auto;
      border-radius: 999px;
    }

    .product-art::before {
      width: 62%;
      height: 68%;
      left: 18%;
      top: 14%;
      background: linear-gradient(180deg, #32405f 0%, #171e31 100%);
      border: 1px solid #415073;
    }

    .product-art::after {
      width: 24%;
      height: 24%;
      right: 12%;
      top: 12%;
      background: #8bd3ff;
      box-shadow: 0 0 0 12px #102133;
    }

    .product-card h3,
    .deal-card h3,
    .story-card h3 {
      font-size: 1.05rem;
      line-height: 1.2;
    }

    .product-meta {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 0.8rem;
      margin-top: 0.8rem;
      color: var(--text-muted);
      font-size: 0.94rem;
    }

    .product-meta strong {
      color: var(--text);
      font-size: 1.05rem;
    }

    .product-button {
      width: 100%;
      margin-top: 0.9rem;
      padding: 0.85rem 1rem;
      background: var(--bg-surface-2);
      color: var(--text);
      border-color: var(--border);
      font-weight: 700;
    }

    .product-button[aria-pressed="true"] {
      background: var(--success);
      color: #06130c;
      border-color: var(--success);
    }

    .deal-layout {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
