    .deal-card.featured {
      grid-column: span 1;
      background:
        radial-gradient(circle at top right, #2c3655 0, #1a2032 28%, #121726 55%, #10131e 100%);
    }

    .deal-card .deal-badge,
    .story-tag {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: #1c2233;
      color: var(--warning);
      border: 1px solid #3b4560;
      font-size: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .deal-card p,
    .story-card p {
      color: var(--text-muted);
      margin-top: 0.8rem;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 0.6rem;
      margin: 1rem 0 1.2rem;
    }

    .countdown div {
      padding: 0.8rem 0.7rem;
      text-align: center;
      background: var(--bg-surface-2);
      border: 1px solid var(--border);
      border-radius: 16px;
    }

    .countdown strong {
      display: block;
      font-size: 1.25rem;
      line-height: 1;
    }

    .countdown span {
      color: var(--text-soft);
      font-size: 0.8rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .deal-grid {
      display: grid;
      gap: 1rem;
    }

    .deal-stack {
      display: grid;
      gap: 1rem;
    }

    .deal-banner {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      padding: 1rem 1.1rem;
      border-radius: var(--radius-md);
      background: var(--bg-surface-2);
