      border: 1px solid var(--border);
      background:
        linear-gradient(135deg, #1f2741 0%, #111723 100%);
      position: relative;
      overflow: hidden;
    }

    .story-visual::before {
      content: "";
      position: absolute;
      inset: 12% 12% 20% 12%;
      border-radius: 20px;
      border: 1px solid #425170;
      background:
        linear-gradient(180deg, #2b3651 0%, #151b29 100%);
    }

    .story-visual::after {
      content: "";
      position: absolute;
      inset: auto 20% 14% 20%;
      height: 9%;
      border-radius: 999px;
      background: #8bd3ff;
      box-shadow: 0 -38px 0 0 #ffc36b, 0 -76px 0 0 #7ee0b2;
