      gap: 1rem;
      align-items: center;
      padding: 1.3rem;
      margin-bottom: 1.5rem;
    }

    .newsletter-card p {
      color: var(--text-muted);
      margin-top: 0.45rem;
    }

    .newsletter-form {
      display: flex;
      gap: 0.75rem;
      min-width: 0;
    }

