      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .newsletter-form input {
      width: min(340px, 100%);
      min-width: 0;
      padding: 0.95rem 1rem;
      border-radius: 999px;
      background: var(--bg-surface-2);
      color: var(--text);
      border: 1px solid var(--border);
    }

    .newsletter-form input::placeholder {
      color: var(--text-soft);
    }

    .newsletter-form button {
      padding: 0.95rem 1.25rem;
      border-radius: 999px;
      border: 1px solid var(--accent);
      background: var(--accent);
      color: var(--accent-contrast);
      font-weight: 800;
      cursor: pointer;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 0.8rem;
      color: var(--success);
      font-weight: 600;
    }

    .footer {
