  <script>
    const chips = Array.from(document.querySelectorAll('.chip'));
    const productCards = Array.from(document.querySelectorAll('.product-card'));
    const bagStatus = document.getElementById('bagStatus');
    const newsletterStatus = document.getElementById('newsletterStatus');
    const countdownEls = {
      days: document.getElementById('days'),
      hours: document.getElementById('hours'),
      minutes: document.getElementById('minutes'),
      seconds: document.getElementById('seconds')
    };
    const newsletterForm = document.getElementById('newsletterForm');
    const saleEndsAt = new Date(Date.now() + 48 * 60 * 60 * 1000);

    function setPressedChip(activeFilter) {
      chips.forEach((chip) => {
        const isActive = chip.dataset.filter === activeFilter;
        chip.setAttribute('aria-pressed', String(isActive));
      });
    }

    function filterProducts(filter) {
      productCards.forEach((card) => {
        const shouldShow = filter === 'all' || card.dataset.category === filter;
        card.classList.toggle('is-hidden', !shouldShow);
      });
    }

    chips.forEach((chip) => {
      chip.addEventListener('click', () => {
        const filter = chip.dataset.filter;
        setPressedChip(filter);
        filterProducts(filter);
      });
    });

    document.querySelectorAll('.product-button').forEach((button) => {
      button.addEventListener('click', () => {
        const pressed = button.getAttribute('aria-pressed') === 'true';
        const nextState = !pressed;
        button.setAttribute('aria-pressed', String(nextState));
        const productName = button.dataset.productName;
        bagStatus.textContent = nextState
          ? `${productName} added to your bag.`
          : `${productName} removed from your bag.`;
      });
    });

    function updateCountdown() {
      const now = new Date();
      const total = Math.max(0, saleEndsAt - now);
      const seconds = Math.floor(total / 1000) % 60;
      const minutes = Math.floor(total / 1000 / 60) % 60;
      const hours = Math.floor(total / 1000 / 60 / 60) % 24;
      const days = Math.floor(total / 1000 / 60 / 60 / 24);

      countdownEls.days.textContent = String(days).padStart(2, '0');
      countdownEls.hours.textContent = String(hours).padStart(2, '0');
      countdownEls.minutes.textContent = String(minutes).padStart(2, '0');
      countdownEls.seconds.textContent = String(seconds).padStart(2, '0');
    }

    updateCountdown();
    setInterval(updateCountdown, 1000);

    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const email = document.getElementById('email');
      if (!newsletterForm.checkValidity()) {
        newsletterForm.reportValidity();
        email.focus();
        return;
      }
      newsletterStatus.textContent = 'Thanks for joining the list. Watch your inbox for the first drop.';
      newsletterForm.reset();
    });
  </script>
